  SELECT 'google-ads-fwxw' AS _fonte, TO_HEX(MD5(TO_JSON_STRING(x))) AS _payload_hash, x.* FROM `vanguardamartech_amazoncopy_g_ads`.`google_ads_amazoncopyad` x UNION ALL
  SELECT 'google-ads-dMx7' AS _fonte, TO_HEX(MD5(TO_JSON_STRING(x))) AS _payload_hash, x.* FROM `vanguardamartech_bigazine_g_ads`.`google_ads_bigazinead` x UNION ALL
  SELECT 'google-ads-x36N' AS _fonte, TO_HEX(MD5(TO_JSON_STRING(x))) AS _payload_hash, x.* FROM `vanguardamartech_arena_tintas_g_ads`.`google_ads_arena_tintasad` x UNION ALL
  SELECT 'google-ads-WxA8' AS _fonte, TO_HEX(MD5(TO_JSON_STRING(x))) AS _payload_hash, x.* FROM `vanguardamartech_ba_eletrica_g_ads`.`google_ads_ba_eletricaad` x UNION ALL
  SELECT 'google-ads-Llsu' AS _fonte, TO_HEX(MD5(TO_JSON_STRING(x))) AS _payload_hash, x.* FROM `vanguardamartech_pmz_grupo_ecomm`.`google_ads_pmz_ecommad` x UNION ALL
  SELECT 'google-ads-NP4k' AS _fonte, TO_HEX(MD5(TO_JSON_STRING(x))) AS _payload_hash, x.* FROM `vanguardamartech_pmz_loja`.`google_pmz_grupo_lojaad` x UNION ALL
  SELECT 'google-ads-PdSr' AS _fonte, TO_HEX(MD5(TO_JSON_STRING(x))) AS _payload_hash, x.* FROM `vanguardamartech_pmz_escola_de_mecanicos`.`google_ads_pmz_escola_mecanicosad` x UNION ALL
  SELECT 'google-ads-3eFc' AS _fonte, TO_HEX(MD5(TO_JSON_STRING(x))) AS _payload_hash, x.* FROM `vanguardamartech_unipar_boa_vista`.`google_ads_unipar_boa_vistaad` x UNION ALL
  SELECT 'google-ads-mvUx' AS _fonte, TO_HEX(MD5(TO_JSON_STRING(x))) AS _payload_hash, x.* FROM `vanguardamartech_unipar_neo_vila`.`google_ads_unipar_neo_vilaad` x UNION ALL
  SELECT 'google-ads-hBlk' AS _fonte, TO_HEX(MD5(TO_JSON_STRING(x))) AS _payload_hash, x.* FROM `vanguardamartech_unipar_torres`.`google_ads_unipar_torresad` x
)
SELECT
  REGEXP_EXTRACT(b.ad_group, r'customers/(\d+)/')   AS id_conta,
  REGEXP_EXTRACT(b.ad_group, r'adGroups/(\d+)')     AS id_grupo_anuncio,
  CAST(b.id AS STRING)                              AS id_anuncio,
  b.ad.type                                         AS tipo,
  b.status                                          AS status,
  b.primary_status                                  AS status_primario,
  b.ad_strength                                     AS forca_anuncio,
  b.policy_summary.approval_status                  AS status_aprovacao,
  b.policy_summary.review_status                    AS status_revisao,
  NULLIF(TRIM(b.ad.name), '')                       AS nome_anuncio,
  b.ad.final_urls[SAFE_OFFSET(0)]                   AS url_final,
  ARRAY_LENGTH(b.ad.final_urls)                     AS qtd_urls_finais,
  ARRAY_LENGTH(b.ad.responsive_search_ad.headlines) AS qtd_titulos,
  ARRAY_TO_STRING(ARRAY(SELECT h.text FROM UNNEST(b.ad.responsive_search_ad.headlines) h), ' | ') AS titulos,
  ARRAY_TO_STRING(ARRAY(SELECT d.text FROM UNNEST(b.ad.responsive_search_ad.descriptions) d), ' | ') AS descricoes,
  b.ad.added_by_google_ads                          AS is_criado_pelo_google,
  CURRENT_TIMESTAMP()                               AS _extraido_at,
  b._fonte,
  b._payload_hash
FROM bruto b
